import{_ as i,j as t,e as a,a6 as o}from"./chunks/framework.BWAB8r3J.js";const u=JSON.parse('{"title":"Quality regression matrix","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quality-regression.md","filePath":"guide/quality-regression.md"}'),n={name:"guide/quality-regression.md"};function s(c,e,r,l,h,d){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="quality-regression-matrix" tabindex="-1">Quality regression matrix <a class="header-anchor" href="#quality-regression-matrix" aria-label="Permalink to &quot;Quality regression matrix&quot;">​</a></h1><p>Issue #17 bổ sung một lớp kiểm tra release-quality cho các component được thêm mới hoặc mở rộng trong PR #7. Mục tiêu là bắt các lỗi chỉ xuất hiện trong browser thật, đồng thời ngăn API public bị lệch giữa implementation, metadata, Storybook và VitePress.</p><h2 id="cac-lenh-chinh" tabindex="-1">Các lệnh chính <a class="header-anchor" href="#cac-lenh-chinh" aria-label="Permalink to &quot;Các lệnh chính&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:browser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality:check</span></span></code></pre></div><p><code>api:check</code> đọc trực tiếp source TypeScript của các component trọng yếu, so sánh <code>props</code>, events và slots với contract đã xác minh trong <code>metadata/quality-contract.ts</code>, đồng thời kiểm tra component vẫn được export, vẫn có entry trong generated registry đúng package và có tài liệu VitePress + Storybook tương ứng.</p><p><code>test:browser</code> chạy hai nhóm regression bằng Chrome/Chromium headless qua Chrome DevTools Protocol:</p><ul><li>browser quality matrix cho field relationships, segmented control, combobox, menu, date picker, notifications và theme tokens;</li><li>browser overlay regressions cho Modal/Drawer, nested focus trap, scroll lock, Escape, outside dismissal, footer geometry và focus restoration.</li></ul><p>CI chạy các kiểm tra này trước build. Sau đó Storybook và VitePress được build production, vì vậy ví dụ quan trọng không chỉ được tìm thấy trong source mà còn phải compile thành công.</p><h2 id="pham-vi-hien-tai" tabindex="-1">Phạm vi hiện tại <a class="header-anchor" href="#pham-vi-hien-tai" aria-label="Permalink to &quot;Phạm vi hiện tại&quot;">​</a></h2><p>Matrix khóa các contract đã từng có regression trong issues #8–#16:</p><ul><li><code>TextInput</code>: label/id, description + error <code>aria-describedby</code>, <code>aria-invalid</code>, native attributes;</li><li><code>SegmentedControl</code>: một keyboard entry point, bỏ qua disabled option, Arrow/Home/End đồng bộ focus và selection;</li><li><code>Combobox</code>: filtering, <code>aria-activedescendant</code>, disabled options, Enter selection;</li><li><code>TagsInput</code>: API contract của props/events/slots, cùng regression test riêng cho form, focus và IME;</li><li><code>Menu</code>: mở từ trigger bằng keyboard, focus item đầu tiên hợp lệ, Home/End/Escape và focus restoration;</li><li><code>Modal</code> / <code>Drawer</code>: nested layers, scroll lock, focus trap/restoration, Escape/outside dismissal và token geometry;</li><li><code>DatePicker</code>: focus vào calendar khi mở, arrow navigation, keyboard selection và return focus;</li><li><code>Notifications</code>: live-region semantics, dismiss control và lifecycle/timing được khóa bởi unit regressions;</li><li>SSR: field/combobox/menu/tooltip IDs phải deterministic giữa hai lần server render; dates có regression SSR riêng.</li></ul><h2 id="api-drift-contract" tabindex="-1">API drift contract <a class="header-anchor" href="#api-drift-contract" aria-label="Permalink to &quot;API drift contract&quot;">​</a></h2><p><code>metadata/quality-contract.ts</code> là contract release-quality cho nhóm component PR #7. Mỗi entry mô tả:</p><ul><li>package public;</li><li>source file;</li><li>danh sách props;</li><li>events;</li><li>slots.</li></ul><p><code>api:check</code> parse AST của <code>defineComponent()</code> thay vì dựa trên regex đơn giản. Nếu implementation thêm/xóa/đổi tên public prop, event hoặc slot mà contract chưa được update, CI sẽ fail. Generated registry tiếp tục đóng vai trò discovery metadata; <code>api:check</code> xác nhận component vẫn xuất hiện ở đúng package, còn <code>quality-contract.ts</code> là lớp metadata chính xác dùng để khóa API public của nhóm component PR #7.</p><h2 id="gioi-han" tabindex="-1">Giới hạn <a class="header-anchor" href="#gioi-han" aria-label="Permalink to &quot;Giới hạn&quot;">​</a></h2><p>Đây không phải application E2E suite. Matrix chỉ kiểm tra public behavior boundary của component library và cố tình giữ fixture nhỏ, deterministic, không phụ thuộc network hay backend. Những luồng sản phẩm, routing, API request hoặc business workflow vẫn thuộc test của application sử dụng doctui.</p><p>Khi sửa một regression browser-visible mới, ưu tiên thêm case vào matrix hiện có thay vì tạo một E2E app riêng. Nếu lỗi chỉ cần DOM/unit test để tái hiện chính xác thì giữ nó ở Vitest và chỉ bổ sung browser case khi behavior phụ thuộc focus thật, pointer, keyboard synthesis, layout hoặc browser lifecycle.</p>`,18)])])}const g=i(n,[["render",s]]);export{u as __pageData,g as default};
